mapper.insert:

    SELECT C##MULTICOTIZADOR.SEQ_USUARIOS_ID_MC.NEXTVAL FROM DUAL

INSERT INTO C##MULTICOTIZADOR.USUARIOS_MC (
I_ID_USUARIO, V_USUARIO, V_EMAIL, V_PASSWORD_HASH, I_ACTIVO, I_ID_ROL
) VALUES (
#{iIdUsuario}, #{vUsuario}, #{vEmail}, #{vPasswordHash}, #{iActivo}, #{iIdRol}
)

mapper.update:
UPDATE C##MULTICOTIZADOR.USUARIOS_MC
SET V_PASSWORD_HASH = #{vPasswordHash}
WHERE I_ID_USUARIO = #{iIdUsuario}

UPDATE C##MULTICOTIZADOR.USUARIOS_MC
SET V_PASSWORD_HASH = #{vPasswordHash}
WHERE V_EMAIL = #{vEmail}

mapper.insert:

    SELECT C##MULTICOTIZADOR.SEQ_PASSWORD_RESET_TOKENS_MC.NEXTVAL FROM DUAL

INSERT INTO C##MULTICOTIZADOR.PASSWORD_RESET_TOKENS (
I_ID_TOKEN, V_TOKEN, V_EMAIL, D_FECHA_CREACION, D_FECHA_EXPIRACION, I_USADO
) VALUES (
#{iIdToken}, #{vToken}, #{vEmail}, #{dFechaCreacion}, #{dFechaExpiracion}, #{iUsado}
)

mapper.update:
UPDATE C##MULTICOTIZADOR.PASSWORD_RESET_TOKENS
SET I_USADO = 1
WHERE V_TOKEN = #{token}
